SELECT id, order_id, reviewer_id, reviewee_id, score, content, create_time
FROM twelve_exchange_review
WHERE order_id = #{orderId} AND reviewer_id = #{reviewerId}
AND tenant_id = #{tenantId}
LIMIT 1

SELECT id, order_id, reviewer_id, reviewee_id, score, content, create_time
FROM twelve_exchange_review
WHERE order_id = #{orderId}
AND tenant_id = #{tenantId}
ORDER BY create_time ASC

SELECT
    COUNT(*) AS reviewCount,
    AVG(score) AS avgScore
FROM twelve_exchange_review
WHERE reviewee_id = #{userId}
AND tenant_id = #{tenantId}
